import {
  Box,
  Stack,
  Typography,
  ToggleButton,
  ToggleButtonGroup,
} from "@mui/material";

import { FactCheckRounded } from "@mui/icons-material";

import ForecastContextBar from "../../../components/layout/ForecastContextBar";

import { useForecastContext } from "../../../contexts/ForecastContext";

import ModelPerformanceKPIs from "../components/ModelPerformanceKPIs";
import OotPerformanceChart from "../components/OotPerformanceChart";
import ModelAccuracyMatrix from "../components/ModelAccuracyMatrix";

import {
  PerformanceHorizon,
  PerformanceTarget,
} from "../types/model-performance.types";

/**
 * =====================================================
 * MODEL PERFORMANCE PAGE  (REDESIGNED)
 * =====================================================
 * Page shell refreshed to match the new dashboard layout.
 * Functionality (KPIs, OOT chart, accuracy matrix) is unchanged.
 */
const ModelPerformancePage = () => {
  const { horizon, metric, entityId } = useForecastContext();

  /*
   * daily   -> tactical daily
   * monthly -> strategic monthly
   */
  const performanceHorizon: PerformanceHorizon =
    horizon === "monthly" ? "monthly" : "daily";

  /*
   * burn -> Input, supply -> Replenishment, stockpile -> Stockpile
   */
  const target: PerformanceTarget =
    metric === "supply" ? "Replenishment" : metric === "stockpile" ? "Stockpile" : "Input";

  const ootMetric: "Input" | "Replenishment" | "Stockpile" = target;

  return (
    <Box sx={{ width: "100%", minHeight: "100%", boxSizing: "border-box" }}>
      <Stack spacing={3}>
        <ForecastContextBar />

        {/* Evaluation view context card */}
        <Box
          sx={{
            bgcolor: "background.paper",
            border: "1px solid #E4EAF3",
            borderRadius: 12,
            boxShadow: "0 10px 30px rgba(16,32,62,0.05)",
            px: { xs: 2.5, md: 4 },
            py: 2.25,
            display: "flex",
            flexWrap: "wrap",
            justifyContent: "space-between",
            alignItems: "center",
            gap: 2,
          }}
        >
          <Stack direction="row" spacing={1.5} alignItems="center" sx={{ minWidth: 0 }}>
            <Box
              sx={{
                width: 44,
                height: 44,
                borderRadius: 2.5,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                bgcolor: "rgba(0,84,166,0.1)",
                color: "primary.main",
              }}
            >
              <FactCheckRounded />
            </Box>
            <Box sx={{ minWidth: 0 }}>
              <Typography variant="subtitle1" fontWeight={800} color="text.primary">
                Evaluation View
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Accuracy metrics for the selected forecast context.
              </Typography>
            </Box>
          </Stack>

          <ToggleButtonGroup exclusive value={performanceHorizon} size="small" disabled sx={{ flexShrink: 0, gap: 1 }}>
            <ToggleButton value="daily" sx={{ fontWeight: 700, borderRadius: '8px !important' }}>
              Tactical Daily
            </ToggleButton>
            <ToggleButton value="monthly" sx={{ fontWeight: 700, borderRadius: '8px !important' }}>
              Strategic Monthly
            </ToggleButton>
          </ToggleButtonGroup>
        </Box>

        {/* Performance dashboard */}
        <Stack spacing={3} minWidth={0}>
          <ModelPerformanceKPIs horizon={performanceHorizon} entityId={entityId} />
          <OotPerformanceChart horizon={performanceHorizon} entityId={entityId} metric={ootMetric} />
          <ModelAccuracyMatrix horizon={performanceHorizon} entityId={entityId} />
        </Stack>
      </Stack>
    </Box>
  );
};

export default ModelPerformancePage;
